#!/usr/bin/env python3
"""Emit one normalized NVMe SMART/Health JSON event per controller."""
import glob
import json
import os
import re
import shutil
import subprocess
import time


def read_sysfs(path):
    try:
        with open(path, encoding="utf-8") as handle:
            return handle.read().strip()
    except OSError:
        return ""


def pick(payload, *names):
    for name in names:
        if name in payload and payload[name] is not None:
            return payload[name]
    return None


def as_int(value):
    if value is None:
        return None
    cleaned = str(value).strip().replace(",", "").rstrip("%")
    try:
        return int(cleaned, 0)
    except ValueError:
        return int(cleaned)


def emit(event):
    print(json.dumps(event, separators=(",", ":"), sort_keys=True), flush=True)


now = int(time.time())
nvme = shutil.which("nvme")
if not nvme:
    emit({"collection_epoch": now, "collection_status": "error", "device": "collector", "collector_error": "nvme executable not found"})
    raise SystemExit(1)

controllers = [path for path in sorted(glob.glob("/sys/class/nvme/nvme*")) if re.fullmatch(r"nvme\d+", os.path.basename(path))]
if not controllers:
    emit({"collection_epoch": now, "collection_status": "error", "device": "collector", "collector_error": "no NVMe controller entries found"})
    raise SystemExit(0)

for sys_path in controllers:
    name = os.path.basename(sys_path)
    device = f"/dev/{name}"
    identity = {
        "collection_epoch": int(time.time()),
        "device": device,
        "model": read_sysfs(os.path.join(sys_path, "model")) or "UNKNOWN",
        "serial_number": read_sysfs(os.path.join(sys_path, "serial")) or "UNKNOWN",
        "firmware_revision": read_sysfs(os.path.join(sys_path, "firmware_rev")) or "UNKNOWN",
    }
    try:
        if identity["serial_number"] == "UNKNOWN":
            raise ValueError("controller serial number is unavailable")
        completed = subprocess.run(
            [nvme, "smart-log", device, "-o", "json"],
            check=False,
            capture_output=True,
            text=True,
            timeout=15,
            env={"PATH": "/usr/sbin:/usr/bin:/sbin:/bin", "LANG": "C"},
        )
        if completed.returncode != 0:
            raise RuntimeError((completed.stderr or f"nvme exited {completed.returncode}").strip()[:240])
        raw = json.loads(completed.stdout)
        event = {
            **identity,
            "collection_status": "ok",
            "critical_warning": as_int(pick(raw, "critical_warning")),
            "available_spare": as_int(pick(raw, "available_spare", "avail_spare")),
            "available_spare_threshold": as_int(pick(raw, "available_spare_threshold", "spare_thresh")),
            "percentage_used": as_int(pick(raw, "percentage_used", "percent_used")),
            "data_units_written": as_int(pick(raw, "data_units_written")),
            "media_errors": as_int(pick(raw, "media_errors")),
            "power_on_hours": as_int(pick(raw, "power_on_hours")),
        }
        required = ("critical_warning", "available_spare", "available_spare_threshold", "percentage_used", "data_units_written", "media_errors", "power_on_hours")
        missing = [field for field in required if event[field] is None]
        if missing:
            raise ValueError("missing required nvme-cli JSON fields: " + ",".join(missing))
        emit(event)
    except (OSError, subprocess.SubprocessError, RuntimeError, ValueError, json.JSONDecodeError) as exc:
        emit({**identity, "collection_status": "error", "collector_error": str(exc)[:240]})
